import json

def exists(path):
    return execute_tool('editor_toolset.toolsets.asset.AssetTools.exists', json.dumps({'path': path}))['returnValue']

def duplicate(source, destination):
    if exists(destination):
        return 'existing'
    ok = execute_tool('editor_toolset.toolsets.asset.AssetTools.duplicate', json.dumps({'path': source, 'new_path': destination}))['returnValue']
    if not ok:
        raise RuntimeError('Failed to duplicate ' + source + ' to ' + destination)
    return 'created'

def run():
    copies = {
        '/ExtractionOps/Input/IA_ExtractionInteract': '/ShooterExplorer/Input/Actions/IA_Interact',
        '/ExtractionOps/Input/IMC_Extraction': '/ShooterCore/Input/Mappings/IMC_ShooterGame',
        '/ExtractionOps/Input/DA_ExtractionInputAddOns': '/ShooterCore/Input/Actions/InputData_ShooterGame_AddOns',
        '/ExtractionOps/Experiences/DA_ExtractionInputActionSet': '/ShooterCore/Experiences/LAS_ShooterGame_SharedInput'
    }
    results = {}
    for destination, source in copies.items():
        results[destination] = duplicate(source, destination)
    if not execute_tool('editor_toolset.toolsets.asset.AssetTools.save_assets', json.dumps({'asset_paths': list(copies.keys())}))['returnValue']:
        raise RuntimeError('Failed to save Week 3 input assets')
    return {'assets': results, 'saved': True}
